/* Language is presentation-only. Domain values and user-authored text never change. */
const LANGUAGE_KEY = 'vuitk-language';
let language = (() => { try { return localStorage.getItem(LANGUAGE_KEY) === 'es' ? 'es' : 'en'; } catch { return 'en'; } })();
const ES_LOOKUP = Object.create(null);
for (const [en, es] of Object.entries(ES_MESSAGES)) {
  ES_LOOKUP[en] = es;
  if (!(en.toUpperCase() in ES_LOOKUP)) ES_LOOKUP[en.toUpperCase()] = es.toUpperCase();
  if (!(en.toLowerCase() in ES_LOOKUP)) ES_LOOKUP[en.toLowerCase()] = es.toLowerCase();
}
const escapeRegex = value => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const ES_PATTERN = new RegExp('(?<![\\p{L}\\p{N}_])(?:' + Object.keys(ES_LOOKUP).sort((a,b)=>b.length-a.length).map(escapeRegex).join('|') + ')(?![\\p{L}\\p{N}_])','gu');
function translateText(source, target = language) {
  if (target !== 'es' || !source.trim()) return source;
  const spaceBefore = source.match(/^\s*/)[0], spaceAfter = source.match(/\s*$/)[0], text = source.trim();
  if (Object.hasOwn(ES_LOOKUP,text)) return spaceBefore+ES_LOOKUP[text]+spaceAfter;
  const patterns = [
    [/^Within (\d+) km of (.+)$/,m=>`A menos de ${m[1]} km de ${m[2]}`],
    [/^(\d+) athletes · approximate city-level distances$/,m=>`${m[1]} deportistas · distancias aproximadas entre ciudades`],
    [/^(\d+)% data coverage · (Limited|Higher) confidence in inputs, not predictive accuracy\.$/,m=>`${m[1]} % de datos disponibles · Confianza ${m[2]==='Limited'?'limitada':'mayor'} en los datos, no en la precisión predictiva.`],
    [/^(\d+) km between city centres/,m=>`${m[1]} km entre centros urbanos`],
    [/^You connected with (.+)\.$/,m=>`Has conectado con ${m[1]}.`],
    [/^Connection request sent to (.+)\.$/,m=>`Solicitud de conexión enviada a ${m[1]}.`],
    [/^Demo acceptance: connected with (.+)\.$/,m=>`Aceptación simulada: has conectado con ${m[1]}.`],
    [/^Registered for (.+) · demo\.$/,m=>`Inscripción en ${translateText(m[1],'es')} · demo.`],
    [/^(.+) result added\.$/,m=>`Resultado añadido: ${translateText(m[1],'es')}.`],
  ];
  for (const [regex, format] of patterns) {
    const m=text.match(regex);
    if(m){const rest=text.slice(m[0].length);return spaceBefore+format(m)+(rest?translateText(rest,'es'):'')+spaceAfter;}
  }
  return source.replace(ES_PATTERN, key=>ES_LOOKUP[key]);
}
function languageControl(compact = false){return `<label class="language-control ${compact?'compact':''}"><span class="sr-only">App language</span><select aria-label="App language" data-language-select onchange="setLanguage(this.value)"><option value="en" ${language==='en'?'selected':''}>${compact?'EN':'English'}</option><option value="es" ${language==='es'?'selected':''}>${compact?'ES':'Español'}</option></select></label>`;}
const originalText = new WeakMap(), originalAttributes = new WeakMap();
let languageObserver = null;
function localizeInterface(){
  languageObserver?.disconnect();
  try {
    document.documentElement.lang=language;
    document.title=language==='es'?'VUITK · Encuentra a tu gente':'VUITK · Find your people';
    document.querySelectorAll('[data-language-select]').forEach(el=>el.value=language);
    // Freeze option identities before changing their displayed labels.
    document.querySelectorAll('option:not([value])').forEach(el=>el.setAttribute('value',el.textContent));
    const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
    while(walker.nextNode()){
      const n=walker.currentNode, parent=n.parentElement;
      if(!parent||parent.closest('script,style,textarea,[data-i18n-skip],[data-language-select]'))continue;
      let entry=originalText.get(n);
      if(!entry||n.nodeValue!==entry.rendered)entry={source:n.nodeValue,rendered:n.nodeValue};
      const rendered=translateText(entry.source);
      if(n.nodeValue!==rendered)n.nodeValue=rendered;
      entry.rendered=rendered;originalText.set(n,entry);
    }
    document.querySelectorAll('[placeholder],[aria-label],[title]').forEach(el=>{
      if(el.closest('[data-i18n-skip]'))return;
      const entries=originalAttributes.get(el)||{};
      for(const attr of ['placeholder','aria-label','title']){
        if(!el.hasAttribute(attr))continue;
        const current=el.getAttribute(attr);let item=entries[attr];
        if(!item||item.rendered!==current)item={source:current,rendered:current};
        item.rendered=translateText(item.source);if(current!==item.rendered)el.setAttribute(attr,item.rendered);entries[attr]=item;
      }
      originalAttributes.set(el,entries);
    });
  } finally {languageObserver?.observe(document.body,{childList:true,subtree:true,characterData:true});}
}
function setLanguage(value){
  if(!['en','es'].includes(value))return;
  language=value;
  try{localStorage.setItem(LANGUAGE_KEY,value)}catch{/* Selection still works for this session. */}
  localizeInterface();
}
function initI18n(){
  languageObserver=new MutationObserver(localizeInterface);
  localizeInterface();
}


