function distance(a,b){if(!CITIES[a]||!CITIES[b])return null;const [la,lo]=CITIES[a],[lb,lp]=CITIES[b];return Math.round(Math.hypot((la-lb)*111,(lo-lp)*83))}
function overlap(a,b){return a.length&&b.length?a.filter(x=>b.includes(x)).length/Math.min(a.length,b.length):null}
function match(p,mode='Training Partners'){
 const u=S.user,d=distance(u.city,p.city),lev=['Beginner','Rookie','Intermediate','Advanced','Elite'];
 const level=u.level&&p.level?Math.max(0,1-Math.abs(lev.indexOf(u.level)-lev.indexOf(p.level))*.25):null;
 const sched=u.days.length&&p.days.length?overlap(u.days,p.days)*.65+(u.time===p.time?.35:0):null;
 const perf=u.pace&&p.pace?Math.max(0,1-Math.abs(u.pace-p.pace)/180):null;
 const comp=u.pace&&p.pace&&p.func?Math.max(0,1-Math.abs((1000-u.pace*1.3)-p.func)/700):null;
 const parts=mode==='Doubles Partners'?[['Competition goals',25,u.category===p.category?1:.4],['Performance fit',25,perf],['Schedule & calendar',20,sched===null?null:sched*.7+(u.date===p.date?.3:0)],['Approximate proximity',15,d===null?null:Math.max(0,1-d/100)],['Running / station balance',15,comp]]:[['Shared goals',25,overlap(u.goals,p.goals)],['Training availability',25,sched],['Similar level',20,level],['Approximate proximity',20,d===null?null:Math.max(0,1-d/100)],['Training preferences',10,u.type===p.type?1:.3]];
 const weight=parts.reduce((s,x)=>s+(x[2]===null?0:x[1]),0);return {value:weight?Math.round(parts.reduce((s,x)=>s+(x[2]===null?0:x[1]*x[2]),0)/weight*100):null,coverage:weight,parts,distance:d};
}
const clamp=x=>Math.max(0,Math.min(1000,Math.round(x)));
function score(){const rec=S.records;const runs=rec.filter(x=>['5 km run','10 km run'].includes(x.type));const row=rec.filter(x=>x.type==='Rowing'&&x.context.startsWith('1000 m'));const comps=rec.filter(x=>x.type==='Competition'&&x.benchmark==='demo-full-solo');const train=rec.filter(x=>x.type==='Training session');const r=runs.length?Math.max(...runs.map(x=>clamp((480-x.seconds/(x.type==='5 km run'?5:10))/300*1000))):null;const f=row.length?Math.max(...row.map(x=>clamp((420-x.seconds)/240*1000))):null;const c=comps.length?clamp((7200-comps[comps.length-1].seconds)/4200*1000):null;const weeks=new Set(train.map(x=>Math.floor(new Date(x.date).getTime()/604800000)));const t=train.length?clamp(weeks.size/4*1000):null;const parts=[['Running',35,r],['Functional',30,f],['Competition',25,c],['Consistency',10,t]];let weight=parts.reduce((n,x)=>n+(x[2]===null?0:x[1]),0);let value=weight?Math.round(parts.reduce((n,x)=>n+(x[2]||0)*x[1],0)/weight):null;return {parts,value,coverage:weight,level:value===null?'Not enough data':['Beginner','Rookie','Intermediate','Advanced','Elite'][Math.min(4,Math.floor(value/200))]}}
function athleticScore(p){if(!p.publicPerformance||p.run===null)return null;return Math.round(p.run*.35+p.func*.3+p.competition*.25+p.consistency*.1)}


