function shell(content){$('app').innerHTML=`<aside class="sidebar"><div class="wordmark">VUITK</div><div class="demo-tag" style="margin-top:16px">THE HYBRID COMMUNITY</div><nav class="nav" aria-label="Main navigation">${['Home','Discover','Performance','Events','Profile'].map(p=>`<button class="${page===p?'active':''}" ${page===p?'aria-current="page"':''} onclick="go('${p}')">${icon(p.toLowerCase())}<span>${p}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="card" style="padding:15px"><span class="pill accent">FREE MEMBER</span><p style="font-size:12px;margin-top:10px">More progress.<br>Better company.</p></div><button class="row mt" onclick="go('Profile')">${avatar(S.user)}<span style="text-align:left">${userText(S.user.name)}<small style="display:block;margin-top:4px">Your athlete profile</small></span></button><p class="demo-tag mt">INTERACTIVE DEMO · LOCAL DATA</p></div></aside><main class="main"><header class="topbar"><span class="breadcrumbs desktop-only">Your community <span style="margin:0 10px">/</span> <span style="color:var(--text)">${page}</span></span><span class="wordmark mobile-only">VUITK</span><div class="top-actions">${languageControl(true)}<span class="pill outline desktop-only">DEMO EXPERIENCE</span><button class="iconbtn" aria-label="Notifications" onclick="notifications()">${icon('bell')}<i class="dot"></i></button><button class="iconbtn" aria-label="Messages" onclick="inbox()">${icon('chat')}</button><button aria-label="Your profile" onclick="go('Profile')">${avatar(S.user)}</button></div></header>${content}<p class="footer-note">VUITK prototype · Fictional athletes & events · Changes saved on this device<br>Independent hybrid fitness community. Not affiliated with HYROX.</p></main>`}
