function home(){let s=score(),people=ATHLETES.filter(p=>!S.blocked.includes(p.id)).map(p=>({...p,match:match(p)})).sort((a,b)=>b.match.value-a.match.value).slice(0,2);return `${heading('YOUR NEXT CHAPTER',`Let’s move, ${userText(S.user.name.split(' ')[0])}.`,`${S.privacy.city?esc(S.user.city)+' · ':''}Better together. Stronger every session.`)}<div class="dashboard"><div><section class="hero"><div class="eyebrow">CONNECT / PERFORM / COMPETE</div><h1>Find your people.<br><span class="lime">Push your limits.</span></h1><p>Your next training partner is closer than you think.</p>${btn('Find Your Match '+icon('arrow'),"go('Discover')")}<svg class="route" viewBox="0 0 240 240" fill="none"><path d="M10 230C170 220 10 80 160 65S80-30 240 15" stroke="#dfff00" stroke-width="1.5"/><path d="M20 250C190 220 35 95 180 80S110-10 250 35" stroke="#dfff00" stroke-width="1.5"/></svg></section><div class="section-title"><h2>Your kind of athletes</h2><button class="link" onclick="go('Discover')">Discover all ↗</button></div><div class="athlete-grid">${people.map(athleteCard).join('')}</div><div class="section-title"><h2>On your radar</h2><button class="link" onclick="go('Events')">All events ↗</button></div>${eventCard(EVENTS[0])}</div><div class="stack"><section class="card score-card"><div class="row between"><h3>Your performance</h3>${icon('performance')}</div>${ring(s)}<div class="row between"><span class="pill accent">${s.level.toUpperCase()}</span><small>Provisional · declared</small></div><div class="mini-metrics mt">${s.parts.slice(0,3).map(x=>`<div><strong>${x[2]??'—'}</strong><small>${x[0]}</small></div>`).join('')}</div><button class="link full mt" onclick="go('Performance')">Explore your performance →</button></section><section class="card"><div class="row between"><h3>Your next connection</h3><span class="pill accent">${Object.values(S.connections).filter(x=>x==='incoming').length} NEW</span></div><p class="muted" style="font-size:12px;margin:12px 0">A shared goal is a good place to start.</p>${btn('View connection requests',"inbox()",true,'full small')}</section><section class="card"><h3>Latest activity</h3>${(S.activity.length?S.activity:[{text:'Clara is connected. Plan your first session.',time:'Demo conversation'},{text:'Júlia sent you a connection request.',time:'Demo request'},{text:'Your community is ready to explore.',time:'Welcome to VUITK'}]).slice(0,4).map(a=>`<div class="activity-item"><div class="activity-icon">${icon('check')}</div><div><p>${esc(a.text)}</p><small>${esc(a.time)}</small></div></div>`).join('')}</section></div></div>`}
function discover(){return `${heading('CONNECT WITH PURPOSE','Find your people.','Shared goals. Compatible schedules. Real progress.')}<div class="tabs" role="tablist">${['Training Partners','Doubles Partners','Community'].map(x=>`<button role="tab" aria-selected="${x===mode}" class="${x===mode?'active':''}" onclick="mode='${x}';render()">${x}</button>`).join('')}</div>${mode==='Community'?groups():`<div class="toolbar"><div class="search">${icon('search')}<input aria-label="Search athletes" placeholder="Search athletes or cities" value="${esc(filters.query)}" oninput="filters.query=this.value;refreshAthletes()"></div>${btn(icon('filter')+' Filters','filterModal()',true)}</div><div class="row between mb"><small id="result-count"></small><span class="pill accent">BEST MATCH FIRST</span></div><div class="chips">${filters.city!=='All locations'?`<span class="pill">${esc(filters.city)}</span>`:''}<span class="pill outline">Within ${Math.min(filters.radius,S.user.radius||100)} km of ${esc(S.user.city)}</span><span class="pill outline">${mode==='Doubles Partners'?'Competition preparation':'Training compatibility'}</span></div><div id="athletes" class="athlete-grid" style="grid-template-columns:repeat(auto-fit,minmax(min(330px,100%),1fr))">${athletesHTML()}</div><p class="note">Match percentages are product estimates, not scientific measures. Open a profile to see the factors and data coverage.</p>`}`}
function athletesHTML(){let list=ranked();return list.length?list.map(athleteCard).join(''):`<div class="empty">${icon('discover')}<h2>Make room for a new connection.</h2><p>No athletes match these filters. Widen your radius or meet the community first.</p>${btn('Reset filters','resetFilters()')}${btn('Explore groups',"mode='Community';render()",true)}</div>`}
function refreshAthletes(){$('athletes').innerHTML=athletesHTML();$('result-count').textContent=ranked().length+' athletes · approximate city-level distances'}
function resetFilters(){filters={query:'',city:'All locations',radius:150,level:'Any level',time:'Any time',goal:'Any goal',type:'Any training',gym:'Any gym',experience:'Any experience',category:'Any goal',maxPace:0};S.user.radius=150;save();closeModal();render()}
function filterModal(){modal('Tune your search',`<form onsubmit="applyFilters(event)"><div class="fields"><div>${select('Location','f-city',['All locations',...Object.keys(CITIES)],filters.city)}</div><div>${select('Athlete level','f-level',['Any level','Beginner','Intermediate','Advanced'],filters.level)}</div><div>${select('Availability','f-time',['Any time','Mornings','Afternoons','Evenings'],filters.time)}</div><div>${select('Training type','f-type',['Any training','Hybrid','Running','Strength'],filters.type)}</div></div>${select('Shared goal','f-goal',['Any goal',...GOALS],filters.goal)}<label class="label" for="f-radius">Search radius · <span id="radius-label">${filters.radius}</span> km</label><input id="f-radius" type="range" min="0" max="150" value="${filters.radius}" oninput="document.getElementById('radius-label').textContent=this.value"><div class="fields"><div>${select('Gym','f-gym',['Any gym','Independent','Northside Hybrid (demo)','Studio Eight (demo)'],filters.gym)}</div><div>${select('Competition experience','f-exp',['Any experience','New to competition','Previous experience'],filters.experience)}</div></div>${mode==='Doubles Partners'?select('Preparation goal (not official categories)','f-category',['Any goal','Finish together','Performance goal'],filters.category):''}${field('Maximum running pace · seconds/km (0 = any)','f-pace',filters.maxPace,'number','min="0" max="900"')}<p class="note">Filters are hard requirements. Athletes without a running pace are excluded only when you set a pace limit.</p><div class="modal-footer"><button class="btn secondary" type="button" onclick="resetFilters()">Reset</button><button class="btn">Apply filters</button></div></form>`)}
function applyFilters(e){e.preventDefault();Object.assign(filters,{city:$('f-city').value,level:$('f-level').value,time:$('f-time').value,type:$('f-type').value,goal:$('f-goal').value,radius:+$('f-radius').value,gym:$('f-gym').value,experience:$('f-exp').value,maxPace:+$('f-pace').value,category:$('f-category')?.value||'Any goal'});S.user.radius=filters.radius;save();closeModal();render()}
function whyMatch(p){let m=match(p,mode);return `<div class="row between"><h2>Why you match</h2><span class="pill accent">${m.value??'—'}% MATCH</span></div><p class="muted" style="font-size:12px;margin-top:10px">${m.coverage}% data coverage · ${m.coverage<80?'Limited':'Higher'} confidence in inputs, not predictive accuracy.</p>${m.parts.map(([label,w,v])=>`<div class="compat-row"><div class="row between"><span>${label}</span><span>${v===null?'Not enough data':Math.round(v*100)+'% fit'} <small>· ${w}% weight</small></span></div><div class="bar"><i style="width:${v===null?0:v*100}%"></i></div></div>`).join('')}<p class="note">${m.distance===null?'Location unknown':m.distance===0?'Same city':m.distance+' km between city centres'} · Approximate only. Missing factors are excluded and remaining weights are normalised. Weights are unvalidated product hypotheses.</p>`}
function athleteProfile(id){let p=ATHLETES.find(x=>x.id===id);if(S.blocked.includes(id))return toast('This athlete is blocked.');let st=S.connections[id],sc=athleticScore(p);modal('Athlete profile',`<div class="profile-cover"></div><div class="profile-header">${avatar(p,true)}<h1>${esc(p.name)} <small style="font:14px 'DM Sans'">${p.age}</small></h1><p class="muted">${p.publicCity?p.city:'City hidden'} · ${p.level}</p><p style="font-size:13px;margin-top:12px">${p.bio}</p></div>${btn(st==='connected'?'Message '+icon('chat'):st==='sent'?'Request Sent':st==='incoming'?'Accept Request':'Connect',`connection(${id})`,false,'full')}${st==='sent'?`<p class="note">This is a fictional athlete. Use the control below to simulate their decision.</p><div class="row">${btn('Simulate acceptance',`acceptDemo(${id})`,true,'small')}${btn('Withdraw request',`withdraw(${id})`,true,'small')}</div>`:''}${st==='incoming'?btn('Decline request',`decline(${id})`,true,'full mt'):''}<div class="section-title"><h2>Training & goals</h2></div><p style="font-size:13px">${p.goals.join(' · ')}</p><div class="athlete-stats mt"><div><small>SCHEDULE</small><span>${p.days.join(', ')} · ${p.time}</span></div><div><small>TRAINING</small><span>${p.type} · ${p.gym}</span></div></div><div class="section-title"><h2>Performance</h2><span class="pill outline">DECLARED · DEMO</span></div>${!p.publicPerformance?'<p class="note">This athlete keeps performance data private.</p>':sc===null?'<p class="note">Starting their journey. No performance records yet — connection is still possible.</p>':`<div class="mini-metrics"><div><strong>${sc}</strong><small>Provisional score</small></div><div><strong>${pace(p.pace)}</strong><small>Running pace /km</small></div><div><strong>${p.func}</strong><small>Functional index</small></div></div><p class="note">Synthetic demonstration components. No official result or verification claimed.</p>`}<div class="section-title"><h2>Competition preparation</h2></div><p style="font-size:13px">${p.experience} · ${p.category}<br>Target window: December 2026. No official registration is claimed.</p><section class="card mt">${whyMatch(p)}</section><div class="row between mt"><button class="link" onclick="reportUser(${id})">Report athlete</button><button class="link" style="color:#f4b2b2" onclick="blockConfirm(${id})">Block athlete</button></div>`)}
function connection(id){let st=S.connections[id];if(S.blocked.includes(id))return toast('Unblock this athlete before connecting.');if(st==='connected')return chat(id);if(st==='sent')return athleteProfile(id);if(st==='incoming'){S.connections[id]='connected';log('You connected with '+ATHLETES[id-1].name+'.');render();return chat(id)}S.connections[id]='sent';log('Connection request sent to '+ATHLETES[id-1].name+'.');render();athleteProfile(id);toast('Request sent · demonstration')}
function acceptDemo(id){S.connections[id]='connected';log('Demo acceptance: connected with '+ATHLETES[id-1].name+'.');render();chat(id)}
function withdraw(id){delete S.connections[id];save();render();athleteProfile(id);toast('Request withdrawn')}
function decline(id){S.connections[id]='declined';save();render();closeModal();toast('Request declined')}
function blockConfirm(id){modal('Block this athlete?',`<p>They will disappear from discovery and your connections. Messaging will be unavailable. You can unblock them in Privacy.</p><div class="modal-footer">${btn('Cancel','closeModal()',true)}${btn('Block athlete',`blockUser(${id})`)}</div>`)}
function blockUser(id){S.blocked.push(id);delete S.connections[id];save();render();closeModal();toast('Athlete blocked')}
function reportUser(id){modal('Report athlete',`<form onsubmit="event.preventDefault();S.reports.push({id:${id},reason:document.getElementById('reason').value});save();closeModal();toast('Demo report recorded locally. No moderation service is connected.')">${select('Reason','reason',['Spam or fake profile','Harassment','Misleading information','Other'],'Spam or fake profile')}<p class="note">Prototype only: this report is stored locally and is not sent to a moderation team.</p><button class="btn full mt">Record demo report</button></form>`)}
function groups(){return `<div class="intro-row mb"><p>Good company, even before your first match.</p><span class="pill outline">COMMUNITY PREVIEW</span></div><div class="event-grid">${GROUPS.map(g=>`<article class="card"><div class="avatar large" style="border-radius:17px;color:var(--lime);margin-bottom:20px">8V</div><span class="pill outline">${g.private?'PRIVATE':'PUBLIC'} GROUP</span><h2 class="mt">${g.name}</h2><p class="muted" style="font-size:12px;margin-top:10px">${g.desc}</p><p class="event-meta">${g.city} · ${g.members} demo members</p><p class="note">${g.next}</p>${btn(S.joined.includes(g.id)?(g.private?'Request pending':'Joined'):(g.private?'Request to join':'Join community'),`joinGroup(${g.id})`,true,'full')}</article>`).join('')}</div><p class="note">Group discovery and local membership states work in this prototype. Group chat and organised calendars are planned for phase 2.</p>`}
function joinGroup(id){if(S.joined.includes(id)){modal('Community membership',`<p>Your demo membership is saved. Group conversations will be available in phase 2.</p>${btn('Leave group',`S.joined=S.joined.filter(x=>x!==${id});save();closeModal();render()`,true,'full mt')}`)}else{S.joined.push(id);save();render();toast(GROUPS[id-1].private?'Join request saved locally':'Welcome to the community · demo')}}
function inbox(){const connected=ATHLETES.filter(p=>S.connections[p.id]==='connected'&&!S.blocked.includes(p.id)),pending=ATHLETES.filter(p=>['incoming','sent'].includes(S.connections[p.id]));modal('Your conversations',`<p class="muted mb">Make a connection. Make a plan.</p>${pending.length?`<span class="eyebrow lime">CONNECTION REQUESTS</span>${pending.map(p=>`<div class="inbox-item">${avatar(p)}<div><strong>${p.name}</strong><p>${S.connections[p.id]==='incoming'?'Wants to train together':'Your request is pending'}</p></div>${btn(S.connections[p.id]==='incoming'?'Review':'View',`athleteProfile(${p.id})`,true,'small')}</div>`).join('')}`:''}<div class="eyebrow mt mb">MESSAGES</div>${connected.length?connected.map(p=>{let ms=S.messages[p.id]||[];return `<button class="inbox-item" onclick="chat(${p.id})">${avatar(p)}<div><strong>${p.name}</strong><p>${ms.length?(ms.at(-1).demo?esc(ms.at(-1).text):userText(ms.at(-1).text)):'Start training together.'}</p></div><small>${esc(ms.at(-1)?.time||'New')}</small>${icon('arrow')}</button>`}).join(''):'<div class="empty"><h3>Your next conversation starts with a connection.</h3></div>'}<p class="note">All profiles and conversations are fictional. Messages stay on this device.</p>`)}
function chat(id){if(S.connections[id]!=='connected'||S.blocked.includes(id))return toast('Connect with this athlete to message.');let p=ATHLETES[id-1];modal(p.name,`<div class="row between"><span class="pill outline">DEMO CONVERSATION</span><button class="link" onclick="athleteProfile(${id})">View profile</button></div><div class="messages" id="messages">${(S.messages[id]||[]).map(m=>`<div class="bubble ${m.me?'me':''}">${m.demo?esc(m.text):userText(m.text)}<small>${esc(m.time)}</small></div>`).join('')||'<p class="muted">Say hello and share what you would like to train.</p>'}</div>${S.sessions.filter(x=>x.partner===id).map((x)=>`<div class="session"><strong>${esc(x.type)} · ${datefmt(x.date)}</strong><p>${esc(x.time)} · ${userText(x.place)}</p><small>${x.accepted?'Confirmed through demo acceptance':'Proposal sent · awaiting demo acceptance'}</small>${!x.accepted?btn('Simulate partner confirmation',`confirmSession(${x.id},${id})`,true,'small full mt'):''}</div>`).join('')}<form class="chat-input" onsubmit="sendMessage(event,${id})"><input id="message-input" placeholder="Start a conversation…" aria-label="Message" maxlength="2000" required><button class="btn" aria-label="Send message">${icon('arrow')}</button></form><button class="link full mt" onclick="planSession(${id})">${icon('events')} Plan a Training Session</button><p class="muted" style="font-size:10px;text-align:center">Local demo · no automatic replies or real recipients</p>`);let m=$('messages');m.scrollTop=m.scrollHeight}
function sendMessage(e,id){e.preventDefault();let t=$('message-input').value.trim();if(!t)return;S.messages[id]??=[];S.messages[id].push({text:t,me:true,time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})});save();chat(id);$('message-input').focus()}
function planSession(id){modal('Plan a training session',`<form onsubmit="saveSession(event,${id})"><div class="fields"><div>${field('Date','session-date','2026-11-07','date','required min="2026-11-02"')}</div><div>${field('Time','session-time','18:00','time','required')}</div></div>${field('Public meeting area','session-place','','text','placeholder="Park or gym — no home addresses" required maxlength="120"')}${select('Training','session-type',['Hybrid','Running','Strength','Technique'],'Hybrid')}<p class="note">A proposal needs both participants’ confirmation. The other athlete’s response can be simulated.</p><button class="btn full mt">Send proposal</button></form>`)}
function saveSession(e,id){e.preventDefault();S.sessions.push({id:Date.now(),partner:id,date:$('session-date').value,time:$('session-time').value,place:$('session-place').value,type:$('session-type').value,accepted:false});log('Training session proposed.');render();chat(id)}
function confirmSession(sid,id){S.sessions.find(x=>x.id===sid).accepted=true;log('Training confirmed through demo acceptance.');render();chat(id)}
function performance(){let s=score(),runs=S.records.filter(x=>x.type==='5 km run').sort((a,b)=>a.date.localeCompare(b.date));return `${heading('PERFORM WITH PURPOSE','Your effort. Made visible.','Track the work. Understand your progress.',btn(icon('plus')+' Add result','addRecord()'))}<div class="dashboard"><section class="card score-card"><div class="row between"><div><span class="eyebrow lime">VUITK SCORE</span><h2 class="mt">A fuller picture of you.</h2></div><span class="pill outline">PROVISIONAL</span></div>${ring(s)}<div class="row between"><span class="pill accent">${s.level.toUpperCase()}</span><small>${s.coverage}% component coverage</small></div><p class="note">An experimental summary, not a validated ranking. Missing components are excluded, never scored as zero. Consistency is shown separately from competitive ability.</p><button class="link" onclick="scoreInfo()">How is this calculated? ↗</button></section><section class="card"><div class="row between"><h3>Running progress</h3><span class="pill outline">5 KM</span></div>${runs.length>1?runChart(runs):`<div class="empty" style="border:0;padding:35px 5px"><div class="big-number" style="font-size:65px">${runs.length?duration(runs[0].seconds):'—'}</div><p>${runs.length?'Your first 5 km baseline. Add another result to see a trend.':'Your progress starts with a first result.'}</p></div>`}<div class="row between mt"><small>${runs.length} comparable results</small>${btn('Log a run',"addRecord('5 km run')",true,'small')}</div><p class="note">Compare the same distance and similar conditions. Manual results are self-declared.</p></section></div><div class="stat-grid">${s.parts.map(([n,w,v])=>`<article class="card"><div class="row between"><small>${n.toUpperCase()}</small><small>${w}%</small></div><strong class="stat-number">${v??'—'} <small>/ 1000</small></strong><div class="bar"><i style="width:${(v||0)/10}%"></i></div><small style="display:block;margin-top:10px">${v===null?'No comparable data':n==='Functional'?'Rowing proxy · limited coverage':n==='Competition'?'Event-specific estimate':n==='Consistency'?'Distinct logged weeks / 4':'Best declared running pace'}</small></article>`).join('')}</div><div class="dashboard"><section class="card"><div class="row between"><h2>Your record book</h2><span class="pill outline">${S.records.length} RESULTS</span></div>${S.records.length?S.records.slice().reverse().map(r=>`<div class="record"><div class="activity-icon">${icon(r.type==='Competition'?'trophy':'performance')}</div><div><strong>${esc(r.type)}</strong><small>${datefmt(r.date)} · ${esc(r.source)}</small><p class="muted" style="font-size:10px">${r.source?.startsWith('Demo')?esc(r.context):userText(r.context)}</p></div><div class="right"><strong>${duration(r.seconds)}</strong><button class="link" style="font-size:10px" onclick="removeRecord(${r.id})">Remove</button></div></div>`).join(''):'<p class="note">No records yet. You can still find compatible training partners.</p>'}</section><section class="card"><span class="eyebrow lime">YOUR NEXT STEP</span><h2 class="mt">Build the full picture.</h2><p class="muted mt">Record a benchmark with its distance, load and conditions. Better context means better comparisons.</p><div class="chips">${STATIONS.map(n=>`<button class="chip" onclick="addRecord('${n}')">${n}</button>`).join('')}</div><button class="link" onclick="connectedApps()">Connected apps ↗</button></section></div>`}
function runChart(runs){let rs=runs.slice(-7),max=Math.max(...rs.map(x=>x.seconds))+30,min=Math.min(...rs.map(x=>x.seconds))-30;let points=rs.map((r,i)=>[20+i*260/(rs.length-1),130-(max-r.seconds)/(max-min)*100]);return `<svg class="chart mt" viewBox="0 0 300 165" role="img" aria-label="5 kilometre times; lower time is better"><line x1="15" y1="30" x2="290" y2="30"/><line x1="15" y1="80" x2="290" y2="80"/><line x1="15" y1="130" x2="290" y2="130"/><polyline points="${points.map(x=>x.join(',')).join(' ')}"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="5" fill="#dfff00"><title>${datefmt(rs[i].date)} · ${duration(rs[i].seconds)}</title></circle><text x="${x}" y="${y-13}" text-anchor="middle">${duration(rs[i].seconds)}</text><text x="${x}" y="157" text-anchor="middle">${rs[i].date.slice(5)}</text>`).join('')}</svg>`}
function scoreInfo(){modal('Understanding VUITK SCORE',`<p>The 0–1000 index is an unvalidated prototype model. It must be calibrated before use with real athletes.</p><div class="note">Running (35%): best 5 km or 10 km average pace, mapped from 8:00/km = 0 to 3:00/km = 1000.<br><br>Functional (30%): only 1000 m rowing is currently comparable; 7:00 = 0 and 3:00 = 1000. Other station records are retained without an invented normalisation.<br><br>Competition (25%): only records explicitly assigned to the demo full simulation / solo scaled reference use the illustrative scale, 120 min = 0 and 50 min = 1000. Other competition results are stored without affecting the score. No leaderboard uses this value.<br><br>Consistency (10%): distinct weeks with a logged session, capped at four weeks. This is regularity, not competitive level.</div><p>Available weights are renormalised. No data means no score. All manual records remain declared. Category thresholds are provisional 200-point bands.</p><p class="note">Matchmaking uses pace and preferences directly; this experimental overall index is not a hard eligibility requirement.</p>`)}
function addRecord(type='5 km run'){modal('Record your progress',`<form onsubmit="saveRecord(event)">${select('Record type','r-type',['5 km run','10 km run',...STATIONS,'Competition','Training session'],type)}<div class="fields"><div>${field('Date','r-date','2026-11-02','date','required max="2026-11-02"')}</div><div>${field('Time · mm:ss or hh:mm:ss','r-time','','text','required placeholder="24:30" pattern="[0-9]{1,3}:[0-5][0-9](:[0-5][0-9])?"')}</div></div>${field('Conditions · distance, load, equipment / event category','r-context','','text','required maxlength="240" placeholder="e.g. 1000 m · Concept2 · damper 5"')}<div class="fields"><div>${field('Event name (competition only)','r-event','','text','maxlength="100"')}</div><div>${field('Position (optional)','r-position','','number','min="1"')}</div></div>${select('Competition score reference (competition records only)','r-benchmark',['Not comparable · store without score','Demo full simulation · solo scaled'],'Not comparable · store without score')}${field('Supporting link (optional, not verification)','r-url','','url','placeholder="https://…"')}<p class="note">Recorded as self-declared. Only 5 km / 10 km runs, 1000 m rowing, competition estimates and sessions affect the provisional score. Rowing context must begin with “1000 m”.</p><div id="r-error" class="error"></div><button class="btn full mt">Save result</button></form>`)}
function saveRecord(e){e.preventDefault();let t=$('r-time').value.split(':').map(Number),sec=t.length===3?t[0]*3600+t[1]*60+t[2]:t[0]*60+t[1],type=$('r-type').value;if(!sec){$('r-error').textContent='Enter a positive time.';return}if(type==='Competition'&&!$('r-event').value.trim()){$('r-error').textContent='Add an event name and its category or conditions.';return}let context=$('r-context').value.trim();S.records.push({id:Date.now(),type,date:$('r-date').value,seconds:sec,context:(type==='Competition'?$('r-event').value+' · ':'')+context,benchmark:$('r-benchmark').value==='Demo full simulation · solo scaled'?'demo-full-solo':null,position:$('r-position').value,url:$('r-url').value,source:'Self-declared'});if(['5 km run','10 km run'].includes(type))S.user.pace=Math.round(sec/(type==='5 km run'?5:10));log(type+' result added.');closeModal();render();toast('Result saved · performance updated')}
function removeRecord(id){modal('Remove this result?',`<p>Your score will be recalculated from the remaining records.</p><div class="modal-footer">${btn('Keep result','closeModal()',true)}${btn('Remove',`S.records=S.records.filter(x=>x.id!==${id});save();closeModal();render();toast('Result removed')`)}</div>`)}
function eventCard(e){let reg=S.registrations[e.id],status=reg?(reg.waitlist?'Waitlist':'Registered'):e.status;return `<article class="card event-tile"><div class="event-art ${e.format.toLowerCase().replace(' ','')}"><span class="pill" style="position:absolute;left:20px;top:18px;background:#151c1fbb">VUITK ${e.format.toUpperCase()}</span><div class="display">${e.name.toUpperCase()}</div></div><div class="event-content"><div class="row between"><small>${datefmt(e.date)} · ${e.time}</small><span class="pill ${status==='Available'||status==='Registered'?'accent':'outline'}">${status.toUpperCase()}</span></div><h3 style="margin-top:13px">${e.name}</h3><div class="event-meta">${icon('pin')}${e.city}<span>·</span>${e.level}</div><div class="row between"><strong>${e.price?'€'+e.price:'Free'} <small>/ athlete</small></strong>${btn(reg?'View registration':'View event',`eventDetail(${e.id})`,true,'small')}</div></div></article>`}
function events(){let list=EVENTS.filter(e=>(eventsTab!=='My Events'||S.registrations[e.id])&&(eventFilters.city==='All locations'||e.city===eventFilters.city)&&(eventFilters.format==='All'||e.format===eventFilters.format)&&(!eventFilters.level||eventFilters.level==='Any level'||e.level===eventFilters.level)&&(!eventFilters.after||e.date>=eventFilters.after)&&(!eventFilters.available||e.status==='Available'));return `${heading('COMPETE TOGETHER','Meet at the start line.','Local experiences. Shared effort. Unforgettable finishes.')}<div class="tabs">${['Explore','My Events'].map(x=>`<button class="${eventsTab===x?'active':''}" onclick="eventsTab='${x}';render()">${x}${x==='My Events'?' · '+Object.keys(S.registrations).length:''}</button>`).join('')}</div><div class="toolbar"><select aria-label="Event city" onchange="eventFilters.city=this.value;render()">${opt(['All locations',...Object.keys(CITIES)],eventFilters.city)}</select>${btn(icon('filter')+' Filters','eventFilterModal()',true)}${btn(icon('events')+' Calendar',"calendar=!calendar;render()",true)}</div><div class="chips mb">${['All','Simulation','Half','Challenge','Team Day'].map(f=>`<button class="chip ${eventFilters.format===f?'active':''}" onclick="eventFilters.format='${f}';render()">${f==='All'?'All formats':f}</button>`).join('')}</div>${calendar?calendarView(list):''}${list.length?`<div class="event-grid">${list.map(eventCard).join('')}</div>`:`<div class="empty">${icon('events')}<h2>${eventsTab==='My Events'?'Your start line is waiting.':'No events in this view.'}</h2><p>${eventsTab==='My Events'?'Explore the community calendar and choose your first experience.':'Try another city or clear the filters.'}</p>${btn('Explore all events',"eventsTab='Explore';eventFilters={city:'All locations',format:'All',after:'',available:false};render()")}</div>`}<p class="note">Every event, venue, price and place count is fictional. Registration and checkout are simulated. No money is collected.</p>`}
function calendarView(list){return `<div class="athlete-grid mb">${[10,11].map(month=>{let first=(new Date(2026,month,1).getDay()+6)%7,n=new Date(2026,month+1,0).getDate();return `<section class="card"><h2>${month===10?'November':'December'} 2026</h2><div class="calendar">${DAYS.map(d=>`<small style="text-align:center">${d}</small>`).join('')}${Array.from({length:first},()=>'<span></span>').join('')}${Array.from({length:n},(_,i)=>{let date='2026-'+String(month+1).padStart(2,'0')+'-'+String(i+1).padStart(2,'0'),events=list.filter(e=>e.date===date);return `<div class="${events.length?'event-day':''}">${i+1}${events.map(e=>`<button style="text-align:left;padding:0;width:100%;min-height:35px" onclick="eventDetail(${e.id})"><small style="color:var(--lime)">${e.format}<br>${e.time}</small></button>`).join('')}</div>`}).join('')}</div></section>`}).join('')}</div>`}
function eventFilterModal(){modal('Event filters',`<form onsubmit="event.preventDefault();eventFilters.after=document.getElementById('e-after').value;eventFilters.level=document.getElementById('e-level').value;eventFilters.available=document.getElementById('e-available').checked;closeModal();render()">${field('From date','e-after',eventFilters.after,'date')}${select('Recommended level','e-level',['Any level','All levels','Beginner','Intermediate'],eventFilters.level||'Any level')}<label class="row mt"><input id="e-available" type="checkbox" ${eventFilters.available?'checked':''}> Only events with places available</label><div class="modal-footer"><button type="button" class="btn secondary" onclick="eventFilters={city:'All locations',format:'All',after:'',available:false};closeModal();render()">Reset</button><button class="btn">Apply</button></div></form>`)}
function eventDetail(id){let e=EVENTS.find(x=>x.id===id),r=S.registrations[id];modal('Event details',`<div class="event-art ${e.format.toLowerCase().replace(' ','')}" style="border-radius:13px;height:190px"><div class="display" style="font-size:44px;max-width:300px">${e.name.toUpperCase()}</div></div><div class="row between mt"><span class="pill accent">VUITK ${e.format.toUpperCase()}</span><span class="pill outline">DEMO EVENT</span></div><p class="mt">${e.desc}</p><div class="athlete-stats mt"><div><small>WHEN</small><span>${datefmt(e.date)} · ${e.time}</span></div><div><small>WHERE</small><span>${e.city}<br>${e.venue}</span></div><div><small>ENTRY</small><span>${e.price?'€'+e.price:'Free'} / athlete</span></div><div><small>AVAILABILITY</small><span>${e.spots?e.spots+' demo places':e.status}</span></div></div><h3 class="mt">The format</h3><p class="muted" style="font-size:13px;margin-top:8px">${e.rules}</p><h3 class="mt">Stations & participation</h3><p class="muted" style="font-size:13px;margin-top:8px">${e.stations}<br>Adults 18+ · ${e.level} · Event-specific scaling<br>Categories: ${e.categories.join(', ')}</p><h3 class="mt">Practical details</h3><p class="muted" style="font-size:13px;margin-top:8px">Arrive 30 minutes before your start. Bring training shoes and water. Demo organiser: VUITK Community. No confirmed sponsors. Simulation timing is illustrative; no official classification is claimed.</p><p class="note">Demo cancellation policy: cancel your local registration at any time. There is no real booking or payment. Real event terms, safety requirements and refund policies must be defined before launch.</p>${e.status==='Completed'?eventResults():''}${r?`<div class="card"><span class="pill accent">${r.waitlist?'ON THE WAITLIST':'YOU’RE REGISTERED'}</span><h3 class="mt">${userText(r.name)}</h3><p>${esc(r.category)} · ${r.code}</p><small>${r.waitlist?'No place is reserved.':'Demo booking only · no payment made'}</small>${btn('Cancel registration',`cancelRegistration(${id})`,true,'full mt')}</div>`:e.status==='Available'?btn('Register · '+(e.price?'€'+e.price:'Free'),`registerForm(${id})`,false,'full'):e.status==='Sold Out'?btn('Join waitlist',`joinWaitlist(${id})`,false,'full'):`<button class="btn secondary full" disabled>${e.status}</button>`}`)}
function registerForm(id){let e=EVENTS.find(x=>x.id===id);modal('Your place at the start',`<span class="pill accent">STEP 1 OF 2 · ${e.format.toUpperCase()}</span><h2 class="mt">${e.name}</h2><form onsubmit="reviewRegistration(event,${id})">${select('Participation category','reg-cat',e.categories,e.categories[0])}${field('Participant name','reg-name',S.user.name,'text','required maxlength="80"')}${field('Email (demo only)','reg-email',S.user.email||'alex@example.com','email','required')}<label class="row mt"><input type="checkbox" id="reg-terms" required> <span style="font-size:12px">I am 18+ and accept the event’s demo terms.</span></label><p class="note">No real booking, email or payment is made. Your details stay on this device.</p><button class="btn full mt">Review registration →</button></form>`)}
let pendingRegistration=null;
function reviewRegistration(e,id){e.preventDefault();pendingRegistration={name:$('reg-name').value.trim(),email:$('reg-email').value,category:$('reg-cat').value};let ev=EVENTS[id-1];modal('Review your registration',`<span class="pill accent">STEP 2 OF 2</span><h2 class="mt">${ev.name}</h2><div class="setting-row"><span>Participant</span><strong>${userText(pendingRegistration.name)}</strong></div><div class="setting-row"><span>Category</span><strong>${esc(pendingRegistration.category)}</strong></div><div class="setting-row"><span>Date</span><strong>${datefmt(ev.date)}</strong></div><div class="setting-row"><span>Demo total</span><strong>€${ev.price}</strong></div><p class="note">${ev.price?'Payment simulation. No card details are requested and you will not be charged.':'This is a free demonstration registration.'}</p><div class="modal-footer">${btn('Back',`registerForm(${id})`,true)}${btn('Confirm demo registration',`finishRegistration(${id})`)}</div>`)}
function finishRegistration(id){if(!pendingRegistration)return;S.registrations[id]={...pendingRegistration,code:'VK-DEMO-'+id+'-'+String(Date.now()).slice(-4),waitlist:false};pendingRegistration=null;log('Registered for '+EVENTS[id-1].name+' · demo.');render();modal('You’re on the start list.',`<div class="empty" style="border:0">${icon('check')}<h1>See you there.</h1><p>${EVENTS[id-1].name}<br>${datefmt(EVENTS[id-1].date)}</p><span class="pill accent">${S.registrations[id].code}</span><p>Demo registration confirmed. No payment has been made.</p>${btn('Go to My Events',"eventsTab='My Events';go('Events')")}</div>`)}
function joinWaitlist(id){S.registrations[id]={name:S.user.name,category:EVENTS[id-1].categories[0],waitlist:true,code:'VK-WAIT-'+id};save();render();eventDetail(id);toast('Added to local demo waitlist')}
function cancelRegistration(id){modal('Cancel your demo registration?',`<p>Your place will be removed from My Events. There is no payment to refund.</p><div class="modal-footer">${btn('Keep registration','closeModal()',true)}${btn('Cancel registration',`delete S.registrations[${id}];save();closeModal();render();toast('Registration cancelled')`)}</div>`)}
function profile(){let s=score();return `${heading('YOUR ATHLETE ID','Built around you.','Your goals, your people, your progress.',btn('Edit Profile','editProfile()',true))}<div class="dashboard"><section class="card"><div class="profile-cover"></div><div class="profile-header">${avatar(S.user,true)}<h1>${userText(S.user.name)}</h1><p class="lime">@${userText(S.user.username)}</p><p class="muted mt">${S.privacy.city?esc(S.user.city):'Location hidden'} · ${esc(S.user.level)}</p><p class="mt">${userText(S.user.bio)}</p></div><div class="mini-metrics"><div><strong>${Object.values(S.connections).filter(x=>x==='connected').length}</strong><small>Connections</small></div><div><strong>${Object.values(S.registrations).filter(x=>!x.waitlist).length}</strong><small>Registrations</small></div><div><strong>${S.records.filter(x=>x.type==='Training session').length}</strong><small>Sessions logged</small></div></div><div class="section-title"><h2>Training preferences</h2><button class="link" onclick="preferences()">Edit ↗</button></div><p class="muted">${S.user.days.join(', ')||'Schedule not added'} · ${S.user.time}</p><div class="chips">${S.user.goals.map(x=>`<span class="pill outline">${esc(x)}</span>`).join('')}</div><p class="note">${esc(S.user.type)} · ${esc(S.user.gym||'Gym not added')}<br>Search radius: ${S.user.radius} km · ${S.privacy.profile?'Profile visible':'Profile hidden'}</p>${btn('Preview shared profile','publicPreview()',true,'full')}</section><div class="stack"><section class="card"><div class="row between"><h3>Your VUITK SCORE</h3><span class="pill accent">${s.level.toUpperCase()}</span></div><strong class="stat-number" style="font-size:65px">${s.value??'—'} <small>/1000</small></strong><p class="muted" style="font-size:12px">Provisional · self-declared data</p><button class="link mt" onclick="go('Performance')">My Performance →</button></section><section class="card"><h2>Your space</h2>${[['My Connections','inbox()'],['My Events',"eventsTab='My Events';go('Events')"],['My Competition Results',"competitionHistory()"],['Training Preferences','preferences()'],['Connected Apps','connectedApps()'],['Settings & Privacy','settings()']].map(([t,a])=>`<button class="setting-row full" onclick="${a}"><span>${t}</span>${icon('arrow')}</button>`).join('')}</section></div></div>`}
function editProfile(){modal('Make it yours',`<form onsubmit="saveProfile(event)"><div class="row">${avatar(S.user,true)}<div><label class="label" for="profile-photo">Profile photo · optional</label><input type="file" id="profile-photo" accept="image/png,image/jpeg,image/webp" style="font-size:11px" onchange="uploadPhoto(this)"></div></div><div class="fields"><div>${field('Display name','p-name',S.user.name,'text','required maxlength="50"')}</div><div>${field('Username','p-username',S.user.username,'text','required pattern="[A-Za-z0-9._]{3,30}"')}</div></div>${select('City / approximate area','p-city',Object.keys(CITIES),S.user.city)}<label class="label" for="p-bio">Your story</label><textarea id="p-bio" maxlength="240">${esc(S.user.bio)}</textarea><p class="note">Only your city is used for approximate matching. Never add your home address.</p><button class="btn full mt">Save profile</button></form>`)}
function uploadPhoto(input){let file=input.files[0];if(!file)return;if(file.size>1500000){input.value='';return toast('Choose an image smaller than 1.5 MB.')}if(!['image/png','image/jpeg','image/webp'].includes(file.type))return toast('Choose a PNG, JPEG or WebP image.');let reader=new FileReader();reader.onload=()=>{S.user.photo=reader.result;save();toast('Photo saved')};reader.readAsDataURL(file)}
function saveProfile(e){e.preventDefault();if(!$('p-name').value.trim())return;Object.assign(S.user,{name:$('p-name').value.trim(),username:$('p-username').value,city:$('p-city').value,bio:$('p-bio').value});save();closeModal();render();toast('Profile updated everywhere')}
function checkChips(xs,selected,prefix){return `<div class="chips">${xs.map((x,i)=>`<label class="chip ${selected.includes(x)?'active':''}" style="display:flex;align-items:center;gap:6px"><input type="checkbox" name="${prefix}" value="${esc(x)}" ${selected.includes(x)?'checked':''} onchange="this.parentElement.classList.toggle('active',this.checked)">${x}</label>`).join('')}</div>`}
const checked=name=>[...document.querySelectorAll(`input[name="${name}"]:checked`)].map(x=>x.value);
function preferenceFields(){return `${select('Your level','pref-level',['Beginner','Rookie','Intermediate','Advanced','Elite'],S.user.level)}<span class="label">Your goals</span>${checkChips(GOALS,S.user.goals,'goals')}<span class="label">Training days</span>${checkChips(DAYS,S.user.days,'days')}<div class="fields"><div>${select('Preferred time','pref-time',['Mornings','Afternoons','Evenings'],S.user.time)}</div><div>${select('Training type','pref-type',['Hybrid','Running','Strength'],S.user.type)}</div><div>${field('Running pace · seconds/km (optional)','pref-pace',S.user.pace||'','number','min="120" max="900"')}</div><div>${field('Travel radius · km','pref-radius',S.user.radius,'number','min="0" max="150" required')}</div></div>${select('Gym (optional)','pref-gym',['Independent','Northside Hybrid (demo)','Studio Eight (demo)'],S.user.gym)}${select('Doubles preparation goal','pref-category',['Finish together','Performance goal'],S.user.category)}${field('Target competition month','pref-date',S.user.date,'month')}`}
function preferences(){modal('Training preferences',`<form onsubmit="savePreferences(event)">${preferenceFields()}<p class="note">These choices directly change your compatibility scores and search radius. Competition goals here are not official entry categories.</p><button class="btn full mt">Save & recalculate matches</button></form>`)}
function readPreferences(){Object.assign(S.user,{level:$('pref-level').value,goals:checked('goals'),days:checked('days'),time:$('pref-time').value,type:$('pref-type').value,pace:+$('pref-pace').value||null,radius:+$('pref-radius').value,gym:$('pref-gym').value,category:$('pref-category').value,date:$('pref-date').value});save()}
function savePreferences(e){e.preventDefault();readPreferences();log('Training preferences updated. Matches recalculated.');closeModal();render();toast('Preferences saved · matches recalculated')}
function publicPreview(){modal('Your shared profile',!S.privacy.profile?'<div class="empty"><h2>Your profile is hidden.</h2><p>Other athletes would not see your profile in discovery.</p></div>':`${avatar(S.user,true)}<h2 class="mt">${userText(S.user.name)}</h2><p class="muted">${S.privacy.city?esc(S.user.city):'City hidden'}</p><p class="mt">${userText(S.user.bio)}</p><p class="note">${S.privacy.performance?'Provisional VUITK SCORE: '+(score().value??'Not enough data')+' · self-declared':'Performance data is private.'}</p><p>${S.user.days.join(', ')} · ${S.user.time}</p>`)}
function settings(){modal('Settings & Privacy',`<span class="eyebrow lime">YOU’RE IN CONTROL</span>${[['profile','Profile visibility','Allow your profile to appear in discovery.'],['performance','Share performance','Show your declared results on your shared profile.'],['city','Share city','Show your approximate city, never your address.'],['notifications','Notifications','Local demo notification preference.']].map(([k,n,d])=>`<div class="setting-row"><div><p>${n}</p><small>${d}</small></div><button class="switch ${S.privacy[k]?'on':''}" role="switch" aria-checked="${S.privacy[k]}" aria-label="${n}" onclick="togglePrivacy('${k}')"></button></div>`).join('')}<div class="setting-row"><div><p>Interface language</p><small>English and Spanish available</small></div>${languageControl()}</div><button class="setting-row full" onclick="connectedApps()">Connected services ${icon('arrow')}</button><button class="setting-row full" onclick="blockedUsers()">Blocked athletes (${S.blocked.length}) ${icon('arrow')}</button><button class="setting-row full" onclick="help()">Help & prototype guide ${icon('arrow')}</button><button class="setting-row full" onclick="logout()">Log out ${icon('logout')}</button><button class="setting-row full" style="color:#ffb8b8" onclick="deleteAccount()">Delete local account & data ${icon('arrow')}</button><p class="note">Local prototype only. No server account, authentication, encrypted messaging or moderation backend is implemented. Privacy switches control the shared-profile preview; no personal data is published to other users.</p>`)}
function togglePrivacy(k){S.privacy[k]=!S.privacy[k];save();render();settings();toast('Privacy preference saved')}
function blockedUsers(){modal('Blocked athletes',S.blocked.length?S.blocked.map(id=>`<div class="setting-row"><span>${ATHLETES[id-1].name}</span>${btn('Unblock',`S.blocked=S.blocked.filter(x=>x!==${id});save();render();blockedUsers()`,true,'small')}</div>`).join(''):'<p class="muted">No blocked athletes.</p>')}
function connectedApps(){modal('Connected apps',`<p class="muted">Your data, brought together. Official integrations are planned for a future release.</p>${['Strava','Garmin Connect','Apple Health'].map(x=>`<div class="setting-row"><strong>${x}</strong><span class="pill outline">NOT AVAILABLE YET</span></div>`).join('')}<p class="note">No service is connected and no data is synchronised. Future connections will require your explicit permission and authorised APIs.</p>`)}
function competitionHistory(){modal('Competition records',S.records.filter(x=>x.type==='Competition').map(r=>`<div class="record"><div><strong>${r.source?.startsWith('Demo')?esc(r.context):userText(r.context)}</strong><small>${datefmt(r.date)} · ${esc(r.source)}</small></div><strong class="right">${duration(r.seconds)}</strong></div>`).join('')||'<p class="note">No competition results yet. You do not need competition experience to use VUITK.</p>')}
function notifications(){modal('Your updates',`<div class="stack">${(S.activity.length?S.activity:[{text:'Júlia would like to connect. Open Messages to review the demo request.',time:'Demo'},{text:'Barcelona Simulation is open for demo registrations.',time:'Demo'}]).map(x=>`<div class="activity-item"><div class="activity-icon">${icon('bell')}</div><div><p>${esc(x.text)}</p><small>${x.time}</small></div></div>`).join('')}</div>`)}
function help(){modal('Explore VUITK',`<div class="stack"><p><strong>Find a partner.</strong> Discover → filter athletes → view a profile → Connect → Simulate acceptance → send a message.</p><p><strong>Join an event.</strong> Events → Barcelona Simulation → register → review → confirm. Find it in My Events.</p><p><strong>Track a result.</strong> Performance → Add result. Try a 5 km time and watch your running component update.</p><p><strong>Try privacy.</strong> Hide performance or your city, then open Preview shared profile.</p><p><strong>Start fresh.</strong> Delete local account & data, then use Get Started to create a beginner profile.</p><p class="note">Working: local navigation, filters, matching, records, profiles and persistence. Simulated: accounts, connections, conversations, event registration and checkout. Future: secure backend, native mobile apps, live users, moderation, official integrations, rankings and AI Coach.</p></div>`)}
function logout(){S.onboarded=false;save();closeModal();render();toast('Logged out of the local demo')}
function deleteAccount(){modal('Delete local data?',`<p>This permanently clears your profile, messages, connections, records and registrations from this browser. The original fictional demo can be loaded again.</p><div class="modal-footer">${btn('Keep my data','closeModal()',true)}${btn('Delete local data',"localStorage.removeItem('vuitk-v1');S=clone(DEFAULT);closeModal();render();toast('Local data deleted')")}</div>`)}
let onboardingStep=0,introStep=0;
function welcome(){$('app').innerHTML=`<main class="welcome"><section class="welcome-art"><img src="data:image/png;base64," alt="Original VUITK brand mark"><div class="eyebrow lime">EIGHT STATIONS. ENDLESS CONNECTIONS.</div><h1 class="mt">Find your people.<br><span class="lime">Push your limits.</span></h1><p>The hybrid community built around you. Train with purpose. Progress together.</p></section><section class="welcome-form">${languageControl()}<span class="eyebrow lime">YOUR NEXT CHAPTER STARTS HERE</span><h1>Great things don’t<br>happen alone.</h1><p class="muted">Find compatible athletes, track your progress and meet at the start line.</p>${btn('Get Started '+icon('arrow'),"introStep=0;showIntro()",false,'full')}${btn('Explore the demo',"S.onboarded=true;save();page='Home';render()",true,'full')}<button class="link full mt" onclick="login()">Already have a local profile? Log In</button><p class="note">Interactive prototype · Fictional community · No real account, messages or payments. Your changes are saved on this device.</p><small style="text-align:center">Independent fitness community · Adults 18+</small></section></main>`}
function showIntro(){let titles=['Find your people.','Track your performance.','Compete together.'],descs=['Shared ambition is a powerful thing. Discover athletes whose goals, schedule and training style work with yours.','Your effort deserves context. Log benchmarks, understand your strengths and follow your progress.','From your first hybrid session to a full simulation. Find local experiences and take the next step together.'];$('app').innerHTML=`<main class="onboard"><div class="row between"><span class="wordmark">VUITK</span>${languageControl(true)}<button class="link" onclick="onboardingStep=0;onboarding()">Skip intro</button></div><div class="onboard-illustration">${icon(['discover','performance','events'][introStep])}</div><div class="eyebrow lime">0${introStep+1} / 03</div><h1>${titles[introStep]}</h1><p class="muted">${descs[introStep]}</p><div class="step-track mt">${[0,1,2].map(i=>`<i class="${i<=introStep?'active':''}"></i>`).join('')}</div>${btn(introStep===2?'Create your local profile':'Continue →',introStep===2?'onboardingStep=0;onboarding()':'introStep++;showIntro()',false,'full')}<button class="link mt" onclick="welcome()">Back to welcome</button></main>`}
function login(){modal('Log in to the local demo',`<p class="muted">No password or server authentication is used. Continue to your profile saved in this browser.</p>${btn('Continue local session',"S.onboarded=true;save();closeModal();render()",false,'full mt')}<button class="link full mt" onclick="modal('Account recovery','<p>There is no remote account to recover. Your prototype data is stored only in this browser. If you cleared browser storage, start a new local profile.</p>')">Forgot your password?</button><p class="note">Apple and Google Sign-In are planned, not connected.</p>`)}
function onboarding(){let u=S.user,titles=['Your journey starts here.','Introduce yourself.','Start where you are.','What brings you here?','Make room for training.','Your data. Your choice.'];let content='';if(onboardingStep===0)content=`${field('Email for your local profile','o-email',u.email,'email','required placeholder="you@example.com"')}<label class="row mt"><input id="o-terms" type="checkbox" required><span style="font-size:12px">I am 18+ and understand this is a local prototype.</span></label><button type="button" class="link" onclick="modal('Demo terms & privacy','<p>This prototype stores data in your browser only. There is no real account, payment, recipient or external synchronisation. Avoid entering sensitive information. You can delete local data in Settings. Production privacy and service terms must be defined before launch.</p>')">Read demo terms & privacy</button><p class="note">No password is requested because secure authentication is not implemented. Apple and Google Sign-In are planned.</p>`;if(onboardingStep===1)content=`${field('Display name','o-name',u.name,'text','required maxlength="50"')}${field('Username','o-username',u.username,'text','required pattern="[A-Za-z0-9._]{3,30}"')}${select('Your city','o-city',Object.keys(CITIES),u.city)}${field('Short bio (optional)','o-bio',u.bio,'text','maxlength="240"')}<p class="note">You can add a photo later. We only need your city, never your address.</p>`;if(onboardingStep===2)content=`${select('Your experience','o-level',['Beginner','Rookie','Intermediate','Advanced','Elite'],'Beginner')}${select('Have you competed before?','o-experience',['No, I’m new','Yes, at least once'],'No, I’m new')}${field('Running pace · seconds/km (optional)','o-pace','','number','min="120" max="900" placeholder="e.g. 300 = 5:00/km"')}${select('Preferred training','o-type',['Hybrid','Running','Strength'],'Hybrid')}<p class="note">No personal bests? No problem. You will start with no score and can still find people to train with.</p>`;if(onboardingStep===3)content=checkChips(GOALS,u.goals,'o-goals');if(onboardingStep===4)content=`<span class="label">Days that usually work</span>${checkChips(DAYS,u.days,'o-days')}${select('Preferred time','o-time',['Mornings','Afternoons','Evenings'],u.time)}${field('Comfortable travel distance · km','o-radius',u.radius,'number','required min="0" max="150"')}${select('Usual gym (optional)','o-gym',['Independent','Northside Hybrid (demo)','Studio Eight (demo)'],u.gym)}`;if(onboardingStep===5)content=`${[['profile','Let athletes discover my profile'],['performance','Share my performance records'],['city','Show my approximate city']].map(([k,t])=>`<label class="setting-row"><span>${t}</span><input type="checkbox" id="o-${k}" ${k==='profile'?'checked':''}></label>`).join('')}<p class="note">Performance and city sharing are off by default. All data remains local in this prototype. You can change visibility and delete your data in Settings.</p>`;$('app').innerHTML=`<main class="onboard"><div class="row between"><span class="wordmark">VUITK</span>${languageControl(true)}<small>PROFILE · ${onboardingStep+1} / 6</small></div><div class="step-track mt">${[0,1,2,3,4,5].map(i=>`<i class="${i<=onboardingStep?'active':''}"></i>`).join('')}</div><span class="eyebrow lime">LET’S GET TO KNOW YOU</span><h1>${titles[onboardingStep]}</h1><form onsubmit="nextOnboarding(event)">${content}<button class="btn full bottom">${onboardingStep===5?'Find my people':'Continue →'}</button>${onboardingStep===2?'<button type="button" class="link full" onclick="nextOnboarding(null,true)">Skip sporting details</button>':''}</form><button class="link mt" onclick="${onboardingStep?'onboardingStep--;onboarding()':'welcome()'}">← Back</button></main>`}
function nextOnboarding(e,skip=false){e?.preventDefault();let u=S.user;if(onboardingStep===0){let email=$('o-email').value;S=clone(DEFAULT);u=S.user;u.email=email;filters.query='';filters.city='All locations';filters.level='Any level';filters.radius=100;mode='Training Partners';}if(onboardingStep===1){u.name=$('o-name').value.trim();if(!u.name)return;u.username=$('o-username').value;u.city=$('o-city').value;u.bio=$('o-bio').value}if(onboardingStep===2){u.level=skip?'Beginner':$('o-level').value;u.pace=skip?null:+$('o-pace').value||null;u.type=skip?'Hybrid':$('o-type').value;S.records=[];S.connections={};S.messages={};S.registrations={};S.activity=[];S.sessions=[]}if(onboardingStep===3)u.goals=checked('o-goals');if(onboardingStep===4){u.days=checked('o-days');u.time=$('o-time').value;u.radius=+$('o-radius').value;u.gym=$('o-gym').value}if(onboardingStep===5){for(let k of ['profile','performance','city'])S.privacy[k]=$('o-'+k).checked;S.onboarded=true;save();page='Discover';render();modal('You’re part of the community.',`<div class="empty" style="border:0">${icon('check')}<h1>Welcome, ${userText(u.name)}.</h1><p>Your goals are set. Your next training partner is waiting to be discovered.</p>${btn('Find my first match','closeModal()')}</div>`);return}save();onboardingStep++;onboarding()}
const renderBase=render;render=function(){renderBase();if(S.onboarded&&page==='Discover'&&mode!=='Community'&&$('result-count'))$('result-count').textContent=ranked().length+' athletes · approximate city-level distances'};
render();

function eventResults(){return `<section class="card mt"><span class="pill outline">DEMO RESULTS · SOLO SCALED</span><h2 class="mt">The finish-line story.</h2><p class="muted mt">Illustrative classification. All athletes used the same demo format. Not official or verified.</p>${[['1','Clara Vidal','1:13:40'],['2','Marc Costa','1:17:25'],['3','Demo athlete','1:19:00']].map(([rank,name,time])=>`<div class="setting-row"><span><strong class="lime">${rank}</strong> · ${name}</span><strong>${time}</strong></div>`).join('')}<p class="note">Example result: 1:19:00. Station splits are unavailable; none are invented.</p>${S.records.some(r=>r.eventId===6)?'<span class="pill accent">EXAMPLE RESULT IN YOUR RECORD BOOK</span>':btn('Add example result to my demo profile','importDemoResult()',true,'full')}</section>`}
function importDemoResult(){if(S.records.some(r=>r.eventId===6))return;S.records.push({id:Date.now(),eventId:6,type:'Competition',date:'2026-10-18',seconds:4740,context:'Autumn Community Simulation · Solo scaled · demo',benchmark:'demo-full-solo',source:'Demo · declared'});log('Example simulation result added.');render();eventDetail(6);toast('Example result imported · not a real achievement')}


initI18n();